<script setup lang="ts">
import { useDemoStore } from '~/stores/demo'
import { useSessionStore } from '~/stores/session'
definePageMeta({layout:'workspace'});import{selectProfilingSet}from'~/demo/selectors.mjs';const route=useRoute(),demo=useDemoStore(),session=useSessionStore();const set=computed(()=>selectProfilingSet(demo.data,session.session||{},String(route.params.id)));const channels=computed(()=>set.value?.channelIds.map((id:string)=>demo.data.channels.find((x:any)=>x.id===id)).filter(Boolean)||[]);function update(id:string,event:Event){const checked=(event.target as HTMLInputElement).checked;const ids=channels.value.map((c:any)=>c.id).filter((x:string)=>x!==id);if(checked)ids.push(id);demo.run({type:'profiling:save',setId:set.value.id,channelIds:ids},session.session||{})}</script>
<template><div v-if="set" class="page-content"><div class="page-title-row"><div><NuxtLink class="flow-link" to="/app/creator-suites">← Creator Suites</NuxtLink><span class="page-label">YOUTUBE CHANNEL PROFILING</span><h1>{{set.name}}</h1><p>{{set.description}}</p></div><span class="tag tag-muted">Public profile comparison</span></div><div class="metric-grid"><div class="metric-panel"><span class="metric-label">Profiles</span><strong class="metric-value">{{channels.length}}</strong><span class="metric-note">Channels in this set</span></div><div class="metric-panel"><span class="metric-label">Combined lifetime views</span><strong class="metric-value">{{(channels.reduce((n:number,c:any)=>n+c.totalViews,0)/1000).toFixed(0)}}K</strong><span class="metric-note">Cumulative public counter</span></div><div class="metric-panel"><span class="metric-label">Listed subscribers</span><strong class="metric-value">{{channels.reduce((n:number,c:any)=>n+(c.subscriberCount||0),0).toLocaleString()}}</strong><span class="metric-note">Public profile counters</span></div></div><section class="panel"><div class="panel-head"><div><h2>Channel profiles</h2><p>Compare topic, subscribers and total public views</p></div><span class="tag tag-muted">SAMPLE DATA</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Channel</th><th>Organization</th><th>Subscribers</th><th>Total views</th><th>Videos</th><th>Include</th></tr></thead><tbody><tr v-for="c in demo.data.channels" :key="c.id"><td><strong>{{c.title}}</strong><div class="secondary-text">{{c.handle || "Public handle not included in snapshot"}}</div></td><td>{{demo.data.organizations.find((o:any)=>o.id===c.organizationId)?.name}}</td><td>{{c.subscriberCount?.toLocaleString()||'Hidden'}}</td><td>{{c.totalViews.toLocaleString()}}</td><td>{{c.videoCount ?? "Not in source snapshot"}}</td><td><label><input type="checkbox" :checked="set.channelIds.includes(c.id)" @change="update(c.id,$event)"><span class="sr-only">Include {{c.title}}</span></label></td></tr></tbody></table></div></section><p class="form-hint">Channel profiling displays public profile and counter data. It does not infer audience demographics or use Gemini.</p></div><div v-else class="page-content"><div class="empty-state">Profile set not found or outside this role's access.</div></div></template>
